#!/usr/bin/env python3
import sys, re, concurrent.futures as cf
sys.path.insert(0, '/tmp/probe')
from tpl import one, build

def clean_err(e):
    e = e or ""
    lines = [l for l in e.splitlines() if 'ERROR' in l or 'Msg(' in l or 'kind:' in l or '"' in l]
    # compact
    m = re.findall(r'"([^"]*)"', e)
    return " | ".join(m[:4]) if m else e.strip()[:200]

def probe(snips, **kw):
    out = {}
    with cf.ThreadPoolExecutor(max_workers=16) as ex:
        futs = {ex.submit(one, s, **kw): s for s in snips}
        for f in futs:
            pass
        for f, s in futs.items():
            v, e = f.result()
            out[s] = (v, clean_err(e) if v is None else None)
    return [(s, out[s][0], out[s][1]) for s in snips]

def pp(snips, **kw):
    for s, v, e in probe(snips, **kw):
        if v is None:
            print("ERR  %-58s %s" % (s, e))
        else:
            print("ok   %-58s %s" % (s, repr(v)))
